public List<User> findUsersByStatusAndAgeCriteria(String status, int minAge) {
    CriteriaBuilder cb = entityManager.getCriteriaBuilder();
    CriteriaQuery<User> query = cb.createQuery(User.class);
    Root<User> root = query.from(User.class);

    Predicate statusPredicate = cb.equal(root.get("status"), status);
    Predicate agePredicate = cb.greaterThan(root.get("age"), minAge);

    query.where(cb.and(statusPredicate, agePredicate));
    return entityManager.createQuery(query).getResultList();
}

